const headers = $input.first().json.headers || {};
const token   = headers['x-internal-token'] || headers['X-Internal-Token'];

if (!token || token !== $env.INTERNAL_WEBHOOK_SECRET) {
  throw new Error('UNAUTHORIZED_REQUEST: invalid or missing token');
}

return [{ json: $input.first().json }];

const leadItems = $items('Load Lead Context');
if (!leadItems || leadItems.length === 0) {
  throw new Error('OUTREACH_FAILED: lead context not found');
}

const lead = leadItems[0].json;
if (!lead.lead_id) {
  throw new Error('OUTREACH_FAILED: lead record is empty');
}

const parseCol = (val) => {
  if (!val) return null;
  if (typeof val === 'object') return val;
  try { return JSON.parse(val); } catch(e) { return null; }
};

const brief            = parseCol(lead.brief)             || {};
const techStack        = parseCol(lead.tech_stack)        || [];
const scoreBreakdown   = parseCol(lead.score_breakdown)   || {};
const icpConfig        = parseCol(lead.icp_config)        || {};
const emailConstraints = parseCol(lead.email_constraints) || {};

const examples = ($items('Load High-Performing Emails') || [])
  .map(i => i.json)
  .filter(e => e.subject && e.body_text);

const toneMap   = { A: 'executive', B: 'consultative', C: 'educational' };
const tier      = lead.icp_tier || 'B';
const tone      = lead.tone || toneMap[tier] || 'consultative';
const wordLimitMap = { A: 120, B: 150, C: 180 };
const wordLimit = emailConstraints.max_words || wordLimitMap[tier] || 150;

return [{
  json: {
    lead,
    brief,
    tech_stack: Array.isArray(techStack) ? techStack : [],
    score_breakdown: scoreBreakdown,
    icp_config: icpConfig,
    email_constraints: emailConstraints,
    examples,
    tier,
    tone,
    word_limit: wordLimit,
    execution_id: $execution.id
  }
}];

