// ── Parse AI Strategy response ─────────────────────────────────────
// Fix 3: robust JSON extraction — strips any LLM preamble text
const raw = $input.first().json?.choices?.[0]?.message?.content
         || $input.first().json?.message?.content
         || '';

let strategy = {};
try {
  // Find first { and last } to handle any preamble/postamble text
  const start = raw.indexOf('{');
  const end   = raw.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('no JSON object found');
  strategy = JSON.parse(raw.slice(start, end + 1));
} catch(e) {
  // Graceful fallback — default strategy so email generation still runs
  strategy = {
    strategy:   'value_led',
    hook:       'I came across your company and wanted to reach out',
    pain_focus: 'operational efficiency',
    reasoning:  'fallback — strategy parse failed: ' + e.message
  };
}

// Pass through full upstream context + strategy
const ctx = $items('Validate Context')[0].json;

return [{
  json: {
    ...ctx,
    strategy
  }
}];

// ── Build outreach prompt v2 ───────────────────────────────────────
// Fix 1: safe() truncator prevents 2000+ token prompts at scale
// Upgrade: injects strategy from AI Strategy Planner
// Upgrade: requests subject_a + subject_b for A/B testing

const {
  lead, brief, tech_stack, examples,
  tone, word_limit, tier, strategy
} = $input.first().json;

// ── safe() — caps any text field injected into the prompt ─────────
const safe = (t, max = 300) => String(t || '').slice(0, max);

// High-performing examples — each body capped at 300 chars
let examplesBlock = 'No examples yet — write from first principles.';
if (examples.length > 0) {
  examplesBlock = examples.map((e, i) =>
    `Example ${i+1} (open: ${Math.round((e.open_rate||0)*100)}%, reply: ${Math.round((e.reply_rate||0)*100)}%):\nSubject: ${safe(e.subject, 80)}\nBody: ${safe(e.body_text, 300)}`
  ).join('\n\n---\n\n');
}

const techMentions   = tech_stack.slice(0, 8).join(', ') || 'not available';
const companySummary = safe(brief.company_summary, 300);
const icpSignals     = safe((brief.icp_signals  || []).slice(0,4).join('; '), 300) || 'none identified';
const painPoints     = safe((brief.pain_points  || []).slice(0,3).join('; '), 300) || 'none identified';
const hooks          = safe((brief.conversation_hooks || []).slice(0,2).join('; '), 200) || 'none available';
const approach       = safe(brief.recommended_approach, 200) || 'consultative value-led outreach';

// Strategy fields — also safe()-capped
const strategyAngle = strategy?.strategy    || 'value_led';
const strategyHook  = safe(strategy?.hook,  150) || hooks;
const strategyFocus = safe(strategy?.pain_focus, 150) || painPoints;

const systemPrompt =
  `You are an elite B2B sales email writer for a SaaS company.\n` +
  `Your emails are concise, personalised, and focused on ONE specific value proposition.\n` +
  `You never use generic openers like "I hope this email finds you well".\n` +
  `You never mention your company name in the subject line.\n` +
  `You always write in first person as the sender.\n` +
  `Output ONLY valid JSON — no markdown, no preamble, no text before or after the JSON object.`;

const userPrompt =
  `Write a cold outreach email. Return a JSON object with EXACTLY these keys:\n` +
  `{\n` +
  `  "subject_a": "variant A — direct/outcome-focused, max 9 words",\n` +
  `  "subject_b": "variant B — curiosity/insight-led, meaningfully different angle, max 9 words",\n` +
  `  "body": "full email body, plain text, no HTML",\n` +
  `  "preview_text": "preview snippet shown in inbox, max 90 chars",\n` +
  `  "personalisation_used": ["exact personalisation elements you actually included in the body"],\n` +
  `  "confidence": 0.0-1.0,\n` +
  `  "confidence_reason": "one sentence explaining the rating"\n` +
  `}\n\n` +
  `SENDER:\n` +
  `Name: ${lead.sender_name || 'Alex'}\n` +
  `Title: ${lead.sender_title || 'Account Executive'}\n` +
  `Company: ${lead.client_company || 'our company'}\n` +
  `Value proposition: ${lead.value_proposition || 'helping teams scale faster'}\n\n` +
  `RECIPIENT:\n` +
  `Name: ${lead.first_name || lead.full_name || 'there'}\n` +
  `Title: ${lead.title || 'Unknown'}\n` +
  `Company: ${lead.company || lead.email_domain}\n` +
  `Industry: ${lead.industry || 'Unknown'}\n` +
  `Size: ${lead.employee_count || 'Unknown'} employees\n` +
  `Location: ${[lead.city, lead.country].filter(Boolean).join(', ') || 'Unknown'}\n` +
  `Funding: ${lead.funding_raised ? '$' + Number(lead.funding_raised).toLocaleString() : 'Unknown'}\n` +
  `Tech stack: ${techMentions}\n` +
  `Company context: ${companySummary}\n\n` +
  `MESSAGING STRATEGY (follow this — chosen for this specific lead):\n` +
  `Angle: ${strategyAngle}\n` +
  `Opening hook: ${strategyHook}\n` +
  `Pain focus: ${strategyFocus}\n\n` +
  `SUPPORTING INTEL:\n` +
  `ICP signals: ${icpSignals}\n` +
  `Pain points: ${painPoints}\n` +
  `Conversation hooks: ${hooks}\n` +
  `Recommended approach: ${approach}\n\n` +
  `EMAIL REQUIREMENTS:\n` +
  `- Tone: ${tone}\n` +
  `- Max words: ${word_limit}\n` +
  `- Tier: ${tier} — ${tier==='A' ? 'executive, direct + outcome-focused' : tier==='B' ? 'manager, insight-led + clear question' : 'growth stage, educate + offer value'}\n` +
  `- First sentence MUST reference something specific about their company or role\n` +
  `- End with ONE clear low-friction CTA\n` +
  `- subject_a and subject_b must be meaningfully different angles\n\n` +
  `HIGH-PERFORMING EXAMPLES (study structure only — do NOT copy wording):\n` +
  examplesBlock;

return [{
  json: {
    ...$input.first().json,
    system_prompt: systemPrompt,
    user_prompt:   userPrompt
  }
}];

// ── Parse OpenAI email response v2 ────────────────────────────────
// Fix 3: robust JSON extraction handles LLM preamble/postamble text
// Fix 5: parses subject_a + subject_b, picks active variant randomly

const raw = $input.first().json?.choices?.[0]?.message?.content
         || $input.first().json?.message?.content
         || '';

let parsed = {};
try {
  // Robust extraction: find first { and last } — ignores any surrounding prose
  const start = raw.indexOf('{');
  const end   = raw.lastIndexOf('}');
  if (start === -1 || end === -1) {
    throw new Error('no JSON object found in response');
  }
  parsed = JSON.parse(raw.slice(start, end + 1));
} catch(e) {
  throw new Error(`PARSE_FAILED: ${e.message} | raw preview: ${raw.slice(0, 200)}`);
}

if (!parsed.body) {
  throw new Error('PARSE_FAILED: OpenAI response missing body');
}
if (!parsed.subject_a && !parsed.subject_b) {
  throw new Error('PARSE_FAILED: OpenAI response missing both subject variants');
}

// ── A/B test: randomly assign which subject variant is sent ────────
// The other is stored for the learning loop in WF-11.
const useVariantA  = Math.random() < 0.5;
const activeSubject  = useVariantA ? (parsed.subject_a || parsed.subject_b) : (parsed.subject_b || parsed.subject_a);
const controlSubject = useVariantA ? parsed.subject_b : parsed.subject_a;
const activeVariant  = useVariantA ? 'A' : 'B';

const ctx       = $items('Validate Context')[0].json;
const wordCount = parsed.body.trim().split(/\s+/).length;

return [{
  json: {
    // Active email
    subject:            activeSubject,
    subject_variant:    activeVariant,
    subject_a:          parsed.subject_a,
    subject_b:          parsed.subject_b,
    subject_control:    controlSubject,
    body:               parsed.body,
    preview_text:       parsed.preview_text || parsed.body.slice(0, 90),
    personalisation_used: parsed.personalisation_used || [],
    word_count:         wordCount,

    // Confidence
    confidence:         parseFloat(parsed.confidence) || 0.5,
    confidence_reason:  parsed.confidence_reason || 'no reason provided',

    // Strategy passthrough
    strategy_used:      $items('Parse Strategy')[0].json.strategy?.strategy || 'unknown',

    // Context
    lead_id:      ctx.lead.lead_id,
    email:        ctx.lead.email,
    company:      ctx.lead.company || ctx.lead.email_domain,
    tier:         ctx.tier,
    tone:         ctx.tone,
    word_limit:   ctx.word_limit,
    pain_points:  ctx.brief.pain_points || [],
    icp_signals:  ctx.brief.icp_signals || [],
    execution_id: $execution.id
  }
}];

// ── Email Guardrail Check v2 ───────────────────────────────────────
// Fix 2: stronger personalisation check — validates body actually
// contains lead-specific data, not just a non-empty array.

const {
  subject, body, word_count, word_limit,
  personalisation_used, lead_id, tier, company
} = $input.first().json;

const violations  = [];
const bodyLower   = body.toLowerCase();
const subjectLow  = subject.toLowerCase();

// 1. Generic opener
if (/i hope this (email|message|finds you)/.test(bodyLower)) {
  violations.push('generic_opener: "I hope this..." detected');
}

// 2. Placeholder leakage
if (/\[.*?\]|\{.*?\}|<[A-Z_]+>|\bUNKNOWN\b|\bNONE\b/i.test(body)) {
  violations.push('placeholder_leakage: unfilled template variable detected');
}

// 3. Word count
if (word_count > word_limit * 1.2) {
  violations.push(`word_count_exceeded: ${word_count} words vs limit ${word_limit}`);
}

// 4. Subject too short
if (!subject || subject.trim().length < 3) {
  violations.push('empty_subject: subject line too short');
}

// 5. Subject spam signals
if (/^re:|^fwd:|\bfree\b|\bguaranteed\b|\burgent\b|!!!/.test(subjectLow)) {
  violations.push('subject_spam_signal: spam trigger word in subject');
}

// 6. Competitor name leakage
const competitors = ($env.COMPETITOR_NAMES || '').split(',').filter(Boolean);
if (competitors.some(c => bodyLower.includes(c.toLowerCase().trim()))) {
  violations.push('competitor_mention: competitor name in body');
}

// 7. Legal risk
if (/guaranteed roi|we promise|100% results|risk.?free guarantee/i.test(bodyLower)) {
  violations.push('legal_risk: unsubstantiated guarantee language');
}

// 8. Fix 2: personalisation CONTENT check ─────────────────────────
// Verify body actually contains the company name — not just that
// personalisation_used array is non-empty (model can hallucinate that).
const companyName = (company || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const bodyStripped = bodyLower.replace(/[^a-z0-9\s]/g, '');
if (companyName && companyName.length > 2 && !bodyStripped.includes(companyName)) {
  violations.push(`missing_company_reference: body does not mention "${company}"`);
}
// Also fail if personalisation_used is entirely empty
if (!personalisation_used || personalisation_used.length === 0) {
  violations.push('no_personalisation: personalisation_used array is empty');
}

// 9. Multiple CTAs
const questionCount = (body.match(/\?/g) || []).length;
if (questionCount > 3) {
  violations.push(`too_many_questions: ${questionCount} question marks detected`);
}

const passed = violations.length === 0;

return [{
  json: {
    ...$input.first().json,
    guardrail_passed:     passed,
    guardrail_violations: violations,
    requires_escalation:  !passed
  }
}];

