const err = $input.first().error || {};
const msg = err.message || 'Unknown error in WF-04';

const isAuth   = msg.includes('UNAUTHORIZED_REQUEST');
const isFailed = msg.includes('OUTREACH_FAILED');
const isParse  = msg.includes('PARSE_FAILED');

return [{
  json: {
    status:       isAuth ? 'unauthorized' : isFailed ? 'context_error' : isParse ? 'parse_error' : 'error',
    message:      msg,
    workflow:     'WF-04',
    timestamp:    new Date().toISOString(),
    execution_id: $execution.id
  }
}];
